48	  return (
49	    <div style={{ borderBottom: "1px solid rgba(255,255,255,0.04)" }}>
50	      {/* .nav-23-dropdown-toggle at 767px: color #fff, justify-content space-between, padding 12px 0 */}
51	      <button
52	        type="button"
53	        onClick={() => setExpanded(!expanded)}
54	        className="flex w-full items-center justify-between px-0 py-3 text-[15px] font-medium text-white transition-colors"
55	      >
56	        {item.label}
57	        {/* .nav-23-dropdown-arrow at 767px: color #21cfff */}
58	        <ChevronDown
59	          className={`h-4 w-4 transition-transform duration-200 ${expanded ? "rotate-180" : ""}`}
60	          style={{ color: "#21cfff" }}
61	        />
62	      </button>
63	
64	      {expanded && (
65	        /* Expanded dropdown children */
66	        <div className="mb-2 flex flex-col gap-0.5">
67	          {item.children.map((child) => {
68	            const content = (
69	              <>
