// ─── Desktop NavDropdown (hover-based) ───────────────────────────────────────

function NavDropdown({ item }: { item: NavItem }) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleMouseEnter = useCallback(() => {
    if (timerRef.current) clearTimeout(timerRef.current);
    setOpen(true);
  }, []);

  const handleMouseLeave = useCallback(() => {
    timerRef.current = setTimeout(() => setOpen(false), 120);
  }, []);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const isSolutions = item.label === "Solutions";

  return (
    // .nav-23-dropdown: margin 0
    <div
      ref={containerRef}
      className="relative"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {/* .nav-23-dropdown-toggle: gap 4px, color #000, bg transparent, border-radius 8px,
          justify-content flex-start, align-items center, padding 8px 8px 8px 10px,
          font-size 16px, line-height 1.5, transition bg-color .3s color .3s */}
      <button
        type="button"
        className="flex cursor-pointer items-center gap-1 rounded-[8px] bg-transparent px-[8px] py-2 pl-[10px] text-[16px] font-normal leading-6 text-black no-underline transition-colors duration-300"
        style={open ? { backgroundColor: "#f5f7f8" } : {}}
        aria-expanded={open}
      >
        <span>{item.label}</span>
        {/* .nav-23-dropdown-arrow: color #082753, w 24px, h 24px, padding 6px 2px 2px, flex */}
        <span
          className="flex h-6 w-6 items-center justify-center transition-transform duration-500"
          style={{
            color: "#082753",
            padding: "6px 2px 2px",
            transform: open ? "rotate(180deg)" : "rotate(0deg)",
          }}
        >
          <ChevronDownIcon />
        </span>
      </button>

      {/* Dropdown list — .nav-23-dropdown-list.w--open: padding-top 20px, bg transparent */}
      {open && (
        <div className="absolute left-0 top-full z-[999999] pt-5">
          {isSolutions ? (
            <SolutionsDropdown items={item.children ?? []} />
          ) : (
            <ResourcesDropdown items={item.children ?? []} />
          )}
        </div>
      )}
    </div>
  );
}

