                href={CTA_NAV[0].href}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex h-auto items-center justify-center whitespace-nowrap rounded-[10px] px-5 py-2 text-[13px] font-bold leading-6 text-[#082753] no-underline transition-colors duration-300 hover:bg-[#082753] hover:text-white"
                style={{
                  backgroundColor: "transparent",
                  border: "1px solid #082753",
                }}
              >
                {CTA_NAV[0].label}
              </a>

              {/* Schedule Demo — .a-gulf-book / .btn-primary:
                  bg-image Group-46729-2.svg + gradient, bg-position 93%, border-radius .75rem,
                  padding .75rem 3rem .75rem 1.25rem, font-size 1rem, font-weight 700, color #fff */}
              <Link
                href={CTA_NAV[1].href}
                className="inline-flex items-center justify-center rounded-[0.75rem] px-[1.25rem] py-[0.75rem] text-[1rem] font-bold leading-7 text-white no-underline transition-colors duration-300"
                style={{
                  backgroundImage:
                    "url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6)",
                  backgroundPosition: "93% center, 0 0",
                  backgroundRepeat: "no-repeat, repeat",
                  backgroundSize: "auto, auto",
                  paddingRight: "3rem",
                  boxShadow: "0 0 5px rgba(0,0,0,0.1)",
                }}
              >
                {CTA_NAV[1].label}
              </Link>
            </div>

            {/* Hamburger — .nav-23-menu-button: bg #000, w 48px, h 48px, border-radius 10px, color #fff
                at 767px: bg var(--blue) */}
            <button
              type="button"
              aria-label="Open navigation menu"
              onClick={() => setMobileOpen(true)}
              className="flex h-12 w-12 shrink-0 items-center justify-center rounded-[10px] text-white md:hidden"
              style={{ backgroundColor: "#082753" }}
            >
              {/* .nav-23-menu-burger: gap 4px, flex col, justify center, align center */}
              <span className="flex flex-col items-center justify-center gap-[4px]">
                {/* .nav-23-menu-line: bg currentColor, border-radius 4px, w 20px, h 2px */}
                <span className="block h-0.5 w-5 rounded-[4px] bg-current" />
                <span className="block h-0.5 w-5 rounded-[4px] bg-current" />
                <span className="block h-0.5 w-5 rounded-[4px] bg-current" />
              </span>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile nav sheet */}
      <MobileNav open={mobileOpen} onClose={() => setMobileOpen(false)} />
    </section>
  );
}

"use client";

import Link from "next/link";
import { useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { NAV_ITEMS, CTA_NAV } from "@/lib/constants/navigation";
import type { NavItem } from "@/types/navigation";

/*
  Webflow mobile nav theme (≤767px):
  - .nav-23-menu: bg #fff, border-bottom 1px solid #c9d2d9, flex col, padding 8px 2%
  - .nav-23-link: justify-content flex-start, align-items center, display flex
  - .nav-23-dropdown-toggle: justify-content space-between, align-items center
  - .nav-23-dropdown-arrow: color #082753 (from nav vars)
  - Nav background when open is dark (#082753) — the Sheet overlay uses this
*/

function ChevronDownIcon({ rotated }: { rotated: boolean }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      className="transition-transform duration-200"
      style={{
        color: "#21cfff",
        transform: rotated ? "rotate(180deg)" : "rotate(0deg)",
      }}
    >
      <path
        d="M11.9997 13.1714L16.9495 8.22168L18.3637 9.63589L11.9997 15.9999L5.63574 9.63589L7.04996 8.22168L11.9997 13.1714Z"
        fill="currentColor"
      />
    </svg>
  );
}

function MobileNavGroup({
  item,
  onNavigate,
}: {
  item: NavItem;
  onNavigate: () => void;
}) {
  const [expanded, setExpanded] = useState(false);

  if (!item.children) {
    return (
      /* .nav-23-link at 767px: justify-content flex-start, align-items center, display flex
         color #fff (dark sheet bg), border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0 */
      <Link
        href={item.href}
        onClick={onNavigate}
        className="flex items-center justify-start px-0 py-3 text-[15px] font-medium text-white no-underline transition-colors"
        style={{ borderBottom: "1px solid rgba(255,255,255,0.04)" }}
      >
        {item.label}
      </Link>
    );
  }

  return (
    <div style={{ borderBottom: "1px solid rgba(255,255,255,0.04)" }}>
      {/* .nav-23-dropdown-toggle at 767px: justify-content space-between, align-items center */}
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center justify-between px-0 py-3 text-[15px] font-medium text-white transition-colors"
      >
        {item.label}
        {/* .nav-23-dropdown-arrow: color #21cfff */}
        <ChevronDownIcon rotated={expanded} />
      </button>

      {expanded && (
        /* .nav-23-dropdown-list.w--open at 767px: padding-top 4px, padding-bottom 4px, position static */
        <div className="mb-2 flex flex-col gap-0.5 py-1">
          {item.children.map((child) => {
            const content = (
              <>
                <span className="text-[14px] font-medium text-white/90">
                  {child.label}
                </span>
                {child.comingSoon && (
                  /* .header-comingsoon-badge */
                  <span
                    className="inline-flex items-center rounded font-bold"
                    style={{
                      color: "#1890ff",
                      backgroundColor: "#e6f7ff",
                      border: "1px solid #91d5ff",
                      padding: "3px 6px",
                      fontSize: "9px",
                      lineHeight: "1em",
                    }}
                  >
                    Coming Soon
                  </span>
                )}
              </>
            );

            if (child.comingSoon) {
              return (
                <div
                  key={child.label}
                  className="flex cursor-default items-center gap-2 rounded-lg px-3 py-2.5 opacity-50"
                >
                  {content}
                </div>
              );
            }

            if (child.external) {
              return (
                <a
                  key={child.label}
                  href={child.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={onNavigate}
                  className="flex items-center gap-2 rounded-lg px-3 py-2.5 no-underline transition-colors hover:bg-white/5"
                >
                  {content}
                </a>
              );
            }

            return (
              <Link
                key={child.label}
                href={child.href}
                onClick={onNavigate}
                className="flex items-center gap-2 rounded-lg px-3 py-2.5 no-underline transition-colors hover:bg-white/5"
              >
                {content}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

export function MobileNav({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  return (
    <Sheet open={open} onOpenChange={onClose}>
      {/* .nav-23-menu at 767px: bg #082753 (dark navy) */}
      <SheetContent
        side="right"
        className="flex w-[300px] flex-col p-0"
        style={{
          backgroundColor: "#082753",
          borderLeft: "1px solid rgba(255,255,255,0.08)",
        }}
      >
        {/* Header row with logo / title */}
        <SheetHeader
          className="px-4 py-4"
          style={{ borderBottom: "1px solid rgba(255,255,255,0.08)" }}
        >
          <div className="flex items-center justify-between">
            <SheetTitle className="text-lg font-bold text-white">
              Boldteq
            </SheetTitle>
          </div>
        </SheetHeader>

        {/* Nav links — .nav-23-menu at 767px: padding 10px 4% (approximated as px-4 py-[10px]) */}
        <div className="flex flex-col overflow-y-auto px-4 py-[10px]">
          {NAV_ITEMS.map((item) => (
            <MobileNavGroup
              key={item.label}
              item={item}
              onNavigate={onClose}
            />
          ))}
        </div>

        {/* CTA buttons at bottom */}
        <div
          className="mt-auto space-y-3 px-4 py-4"
          style={{ borderTop: "1px solid rgba(255,255,255,0.08)" }}
        >
          {/* Login — white-bordered button on dark bg */}
          <a
            href={CTA_NAV[0].href}
            target="_blank"
            rel="noopener noreferrer"
            onClick={onClose}
            className="flex w-full items-center justify-center rounded-[10px] border px-5 py-2.5 text-[13px] font-bold text-white no-underline transition-colors hover:bg-white/10"
            style={{ borderColor: "rgba(255,255,255,0.3)" }}
          >
            {CTA_NAV[0].label}
          </a>

          {/* Schedule Demo — gradient button */}
          <Link
            href={CTA_NAV[1].href}
            onClick={onClose}
            className="flex w-full items-center justify-center rounded-[0.75rem] px-5 py-2.5 text-[13px] font-bold text-white no-underline"
            style={{
              backgroundImage:
                "url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6)",
              backgroundPosition: "93% center, 0 0",
              backgroundRepeat: "no-repeat, repeat",
              backgroundSize: "auto, auto",
            }}
          >
            {CTA_NAV[1].label}
          </Link>
        </div>
      </SheetContent>
    </Sheet>
  );
}
